use std :: path :: Path ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Removes backslash escapes from a string (e.g. `\\ ` becomes ` `)."] # [doc = ""] # [doc = " Many terminals (Ghostty, iTerm2, etc.) backslash-escape spaces when"] # [doc = " drag-and-dropping file paths, producing strings like"] # [doc = " `/path/my\\ folder/file.txt`. This helper un-escapes them so the path"] # [doc = " can be resolved against the filesystem."] # [doc = ""] # [doc = " Returns `None` if no backslash escapes were found (i.e. the input is"] # [doc = " already clean), allowing callers to skip redundant `is_file()` checks."] fn unescape_backslashes (s : & str) -> Option < String > { if ! s . contains ('\\') { return None ; } let mut out = String :: with_capacity (s . len ()) ; let mut chars = s . chars () ; while let Some (c) = chars . next () { if c == '\\' { if let Some (next) = chars . next () { out . push (next) ; } else { out . push (c) ; } } else { out . push (c) ; } } Some (out) }